INSERT INTO news (title, icon_emoji, category, summary, views, published_at, sort_order) VALUES
('公司召开2026年夏季供水保障工作动员大会', '🎤', 'meeting', '5月20日上午，公司在八楼会议室召开2026年夏季供水保障工作动员大会。会议全面部署了今夏高峰供水期间的生产调度、管网巡查、应急抢险等重点工作，确保夏季高峰期全市供水安全稳定。', 1268, '2026-05-20', 1),
('第三水厂深度处理工艺升级改造项目顺利通过验收', '🏗️', 'project', '经过6个月的紧张施工，第三水厂臭氧-活性炭深度处理工艺升级改造项目于5月18日正式通过竣工验收。该项目投运后，出厂水水质将全面优于国家《生活饮用水卫生标准》GB5749-2022最新要求。', 985, '2026-05-18', 2),
('全省供水行业安全生产现场交流会在我司召开', '🏅', 'hot', '5月14日至15日，由湖南省住建厅主办的全省供水行业安全生产现场交流会在湘潭召开。来自全省14个市州的供水企业代表共计120余人参加会议，现场观摩了我司安全标准化建设和应急演练。', 1432, '2026-05-15', 3),
('"智慧水务云平台"获省级数字化转型示范项目称号', '💻', 'project', '省工信厅近日公布了2026年度省级数字化转型示范项目名单，我司"智慧水务云平台"项目成功入选。该平台整合了生产调度、管网GIS、营销服务、水质监测等8大业务系统，实现了全业务流程数字化管理。', 876, '2026-05-12', 4),
('岳塘区老旧管网改造二期工程正式启动，惠及3万居民', '🔧', 'project', '5月8日，岳塘区老旧供水管网改造二期工程在书院路街道正式开工。本次改造涉及书院路、建设南路等5条道路共8.6公里供水主管网，预计9月底完工，将惠及沿线约3万居民。', 752, '2026-05-08', 5),
('公司荣获"湖南省绿色工厂"称号', '🌱', 'hot', '省工信厅、省生态环境厅联合公布2026年度"湖南省绿色工厂"名单，我司凭借光伏发电、雨水回收、节能降耗等绿色生产实践成功入选，成为全省供水行业首家获此称号的企业。', 645, '2026-05-05', 6),
('公司与湖南科技大学签署产学研合作协议', '🤝', 'meeting', '4月28日，我司与湖南科技大学土木工程学院在图书馆报告厅签署产学研合作协议。双方将在供水管网漏损控制、水处理新材料研发、智慧水务算法优化等领域开展深度合作。', 523, '2026-04-28', 7),
('公司工会获评"全国模范职工之家"', '🎖️', 'party', '中华全国总工会近日表彰了一批全国模范职工之家，我司工会委员会光荣上榜。这是继2024年获评省级模范职工之家后，公司工会工作取得的又一项国家级荣誉。', 412, '2026-04-22', 8),
('水质检测中心通过CNAS国家认可复评审', '🔬', 'project', '4月16日至18日，中国合格评定国家认可委员会（CNAS）专家组对我司水质检测中心进行为期三天的现场复评审。检测中心106项水质指标检测能力全部通过评审，继续保持国家认可实验室资质。', 398, '2026-04-18', 9),
('2026年"世界水日""中国水周"系列活动圆满收官', '📢', 'hot', '围绕第三十四届"世界水日"和第三十七届"中国水周"主题，公司组织开展了水厂开放日、社区节水宣传、中小学生水情教育等系列公益活动，累计接待市民参观600余人次。', 567, '2026-04-12', 10),
('二水厂配电系统升级改造圆满完成', '⚡', 'project', '经过连续15天的紧张施工，二水厂10kV配电系统升级改造项目于4月7日顺利完工并一次送电成功。新系统采用智能化配电设备，供电可靠性大幅提升，为夏季高峰供水提供了坚实的电力保障。', 341, '2026-04-08', 11),
('公司召开2026年党风廉政建设工作推进会', '📋', 'party', '4月2日，公司党委召开2026年党风廉政建设工作推进会，深入学习贯彻上级纪委全会精神，总结2025年工作成效，安排部署2026年重点任务，并组织中层以上干部签订廉洁从业承诺书。', 289, '2026-04-02', 12),
('公司客服中心获"湖南省工人先锋号"荣誉称号', '🏆', 'hot', '湖南省总工会日前表彰2026年湖南省工人先锋号，我司客服中心凭借"15分钟响应、2小时到场、24小时办结"的服务承诺和98.6%的用户满意度获此殊荣。', 478, '2026-03-25', 13),
('湘潭市二次供水管理办法正式施行，公司参与起草', '💡', 'meeting', '《湘潭市二次供水管理办法》经市政府常务会议审议通过，于3月15日正式施行。作为主要起草参与单位，我司在技术标准、管理规范等方面贡献了大量实践经验。', 534, '2026-03-18', 14),
('公司举办2026年度新员工入职培训暨"师带徒"签约仪式', '🧑‍🏫', 'party', '3月9日至10日，公司举办2026年度新员工入职培训，来自各高校的28名新员工参加培训。培训结束后举行了"师带徒"签约仪式，18对师徒现场签订培养协议。', 356, '2026-03-10', 15),
('"湘潭供水"微信小程序升级至3.0版本', '📱', 'project', '"湘潭供水"微信小程序3.0版本于3月5日正式上线。新版本新增了用水报装进度查询、电子发票自助开具、用水异常智能预警等功能，用户体验全面优化。', 689, '2026-03-05', 16),
('公司全力应对寒潮天气，抢修队伍24小时待命', '❄️', 'hot', '2月19日晚起，湘潭市遭遇强寒潮天气，最低气温降至-3℃。公司迅速启动防冻保供应急预案，6支抢修队伍、120余名抢修人员24小时待命，累计处理冻管、爆表等工单230余件。', 832, '2026-02-20', 17),
('公司举办2026年迎新春联欢会暨年度表彰大会', '🎆', 'party', '1月24日下午，公司2026年迎新春联欢会暨2025年度表彰大会在湘潭大剧院隆重举行。大会对2025年度先进集体和先进个人进行了表彰，各部门自编自演的文艺节目赢得阵阵掌声。', 1056, '2026-01-25', 18),
('公司开展岁末年初安全生产大检查专项行动', '🔍', 'meeting', '为确保春节期间供水安全，公司于1月10日至14日组织开展了岁末年初安全生产大检查专项行动，对各水厂、加压站、管网设施进行全面排查，发现并整改隐患32项。', 445, '2026-01-15', 19),
('公司召开2025年度工作总结暨2026年工作部署大会', '📊', 'meeting', '1月8日，公司召开2025年度工作总结暨2026年工作部署大会。会议总结了2025年公司在供水保障、经营指标、项目建设等方面取得的成绩，明确了2026年"提质增效、智慧赋能、绿色发展"的工作主线。', 712, '2026-01-08', 20),
('湘江枯水期水源保障联合演练成功举行', '🌊', 'project', '12月20日，由市水利局牵头，我司与环保、水文、气象等部门联合开展了湘江枯水期水源保障应急演练，模拟湘江水位持续下降情况下应急供水调度全流程，检验了应急预案的可操作性。', 398, '2025-12-22', 21),
('九华加压站扩建工程竣工投入运行', '🏗️', 'project', '经过8个月的建设，九华加压站扩建工程于12月12日正式竣工投运。扩建后加压站的日供水能力由3万吨提升至6万吨，将有效缓解九华经开区及周边区域高峰期供水压力不足的问题。', 523, '2025-12-15', 22),
('公司档案管理获评"湖南省档案工作规范化管理示范单位"', '📚', 'meeting', '省档案局近日公布了2025年度全省档案工作规范化管理示范单位名单，我司因档案管理制度健全、数字化率高、利用效果好等优势成功入选。', 267, '2025-12-08', 23),
('公司完成2025年度中层管理人员轮岗交流工作', '🔄', 'party', '为加强干部队伍建设，促进多岗位锻炼，公司于11月底完成了2025年度中层管理人员轮岗交流工作，涉及生产、营销、行政等8个部门的12名中层干部。', 389, '2025-12-01', 24);
