('2025年度企业社会责任报告正式发布', '📖', 'announce', '全文共8章42页', 312, '2026-05-10', 5),
('5月15日岳塘区建设南路DN400管道迁改停水通知', '⚠️', 'stop', '影响范围：建设南路及周边', 1421, '2026-05-13', 6),
('紧急通告：湘江原水浊度异常升高，已启动应急处置措施', '🚧', 'urgent', '出厂水质达标，请放心使用', 2387, '2026-05-08', 7),
('2026-2027年度管网抢修材料框架协议采购招标公告', '📊', 'public', '投标截止：6月5日', 356, '2026-05-06', 8),
('2026年4月水质检测报告发布公告', '📋', 'announce', '106项指标全部达标', 567, '2026-04-28', 9),
('关于2026年"五一"劳动节期间营业时间调整的通知', '🔔', 'notify', '5月1日-3日休息', 876, '2026-04-25', 10),
('第三水厂深度处理工艺改造项目竣工结算审计服务招标公告', '📊', 'public', '开标时间：5月22日', 423, '2026-04-20', 11),
('4月18日九华经开区莲城大道DN500管网维修停水通知', '⚠️', 'stop', '影响范围：莲城大道两侧', 1234, '2026-04-16', 12);
INSERT INTO photo_news (title, icon_emoji, background_gradient, section, album_category, views, published_at, is_featured_main, is_featured_side, sort_order) VALUES
INSERT INTO media_coverage (title, source_name, source_slug, summary, publication_info, views, published_at, sort_order) VALUES
('湘潭中环水务：以"智慧水"润泽"幸福城"', '湖南日报', 'hnrb', '5月20日，《湖南日报》第4版整版报道。记者从智慧水务调度中心、水质检测实验室到管网抢修一线，全景式展现湘潭中环水务以科技赋能、品质服务守护城市供水安全的生动实践。文章称，湘潭中环水务的数字化转型经验值得全省供水行业借鉴推广。', '湖南日报 · 第4版', 3256, '2026-05-20', 1),
('连续8年获评省级先进单位，湘潭这家供水企业有何秘诀？', '红网', 'hw', '5月13日红网深度报道。从"一个电话就上门"的服务承诺，到"从源头到龙头"的全流程水质管控，再到"让数据多跑路、群众少跑腿"的智慧服务体系建设——红网记者用一周时间深入采访，揭秘湘潭中环水务连续8年保持省级先进的金字招牌背后故事。', '红网 · 深度', 5876, '2026-05-13', 2),
('水质达标率99.8%的背后：一个水厂的24小时', '湘潭日报', 'xtrb', '5月9日《湘潭日报》头版刊发。记者跟随第三水厂运转班组，记录下从凌晨4点原水进厂到深夜12点管网末梢水质监测的完整24小时。报道以真实细腻的笔触呈现了一线供水人的日常坚守与精益求精的职业精神。', '湘潭日报 · 头版', 4321, '2026-05-09', 3),
('湘潭市大力推进供水管网智慧化改造', '中国水利报', 'zgslb', '5月5日《中国水利报》第2版。报道重点关注湘潭市近年来供水管网智慧化改造成效：岳塘区8.6公里老旧管网改造、全市管网GIS系统全覆盖、DMA分区计量漏损控制等，湘潭中环水务作为实施主体在其中发挥了关键作用。', '中国水利报 · 第2版', 2145, '2026-05-05', 4),
('湖南新闻联播：湘潭供水企业"绿色工厂"创建纪实', '湖南卫视', 'hntv', '4月28日湖南卫视《湖南新闻联播》播出2分30秒专题报道。节目组实地探访了我司光伏发电站、雨水回收系统、排泥水处理设施等绿色生产项目，称我司为"全省供水行业绿色发展的先行者"。', '湖南卫视 · 新闻联播', 8902, '2026-04-28', 5),
('世界水日特写：300名市民走进湘潭一水厂探秘"一滴水的旅程"', '红网', 'hw', '3月22日红网图文报道。在世界水日当天，湘潭中环水务举办水厂开放日活动，邀请300余名市民代表走进第一水厂，零距离参观取水、混凝、沉淀、过滤、消毒等全制水环节，增强了公众节水护水意识。', '红网 · 图文', 6543, '2026-03-22', 6),
('"指尖上的供水服务"——湘潭供水小程序3.0版用户体验记', '湘潭日报', 'xtrb', '3月10日《湘潭日报》民生版报道。"湘潭供水"微信小程序3.0版上线后，记者以普通用户身份体验了在线缴费、报装进度查询、电子发票开具、用水异常预警等新功能，称"操作便捷、体验流畅"。', '湘潭日报 · 民生版', 3876, '2026-03-10', 7),
('湘潭中环水务开展"我为群众办实事"系列活动取得显著成效', '人民网', 'rmw', '2月15日人民网湖南频道报道。文章梳理了公司2025年以来开展的"我为群众办实事"系列活动：老旧小区供水设施免费检修、独居老人用水关爱行动、社区用水知识讲座等，累计服务群众超过2万人次。', '人民网 · 湖南频道', 4567, '2026-02-15', 8),
('寒潮中的"逆行者"——湘潭供水抢修队24小时守护城市温暖', '湖南日报', 'hnrb', '2月21日《湖南日报》社会版。2月19日湘潭遭遇强寒潮，最低气温降至-3℃。报道记录了我司6支抢修队伍120余名队员在寒风中连续奋战保供水的感人故事。文章配发了抢修工人凌晨在冰冷的泥水中作业的现场图片。', '湖南日报 · 社会版', 7234, '2026-02-21', 9),
('湘潭市积极探索二次供水管理新模式', '中国建设报', 'hnjsb', '1月18日《中国建设报》报道。文章以湘潭市新近施行的《湘潭市二次供水管理办法》为切入点，介绍了湘潭中环水务在二次供水设施建设标准、运维管理和水质监测等方面的创新实践和先行探索。', '中国建设报 · 第3版', 1876, '2026-01-18', 10);
